pragma solidity ^0.8.23;

import "@openzeppelin/contracts/utils/Strings.sol";

library SVG {
    using Strings for uint256;

    bytes16 internal constant ALPHABET = "0123456789abcdef";

    function formatted(
        uint256 _amount,
        uint256 _decimals,
        uint256 _precision
    ) internal pure returns (string memory) {
        uint lExponent = 10 ** _decimals;
        uint left = (_amount / lExponent);

        uint rExponent = 10 ** (_decimals - _precision);
        uint mod = 10 ** _precision;
        uint right = (_amount / rExponent) % mod;

        string memory leftStr = left.toString();
        string memory rightStr = right.toString();

        uint256 fill = _precision - bytes(rightStr).length;

        if (fill == 4) return string(leftStr);

        for (uint256 i = 0; i < fill; i++) {
            rightStr = string(abi.encodePacked("0", rightStr));
        }

        return string(abi.encodePacked(leftStr, ".", rightStr));
    }

    function gradient(
        string[] memory _colors
    ) internal pure returns (string memory) {
        return
            string.concat(
                '<defs><linearGradient id="grad-anim" x1="0%" y1="0%" x2="100%" y2="100%">',
                stopTag(_colors, "0%"),
                stopTag(_colors, "100%"),
                "</linearGradient></defs>"
            );
    }

    function stopTag(
        string[] memory _colors,
        string memory _offset
    ) internal pure returns (string memory) {
        return
            string.concat(
                '<stop offset="',
                _offset,
                '" stop-color="',
                _colors[0],
                '"><animate attributeName="stop-color" values="',
                _colors[0],
                ";",
                _colors[2],
                ";",
                _colors[1],
                ";",
                _colors[0],
                '" dur="7s" repeatCount="indefinite"/></stop>'
            );
    }

    function sideText(
        string memory _text,
        bytes memory _transform,
        bytes memory _anchor
    ) internal pure returns (bytes memory) {
        return
            abi.encodePacked(
                '<text class="small" transform="',
                _transform,
                '" style="text-anchor:',
                _anchor,
                '" fill="#FFF">',
                _text,
                "</text>"
            );
    }

    function titleStack(
        uint256 _x,
        uint256 _y,
        bytes memory _sub,
        bytes memory _title
    ) internal pure returns (bytes memory) {
        return
            abi.encodePacked(
                '<text class="title" transform="translate(',
                _x.toString(),
                ",",
                _y.toString(),
                ')"><tspan class="alpha" x="0">',
                _sub,
                '</tspan><tspan x="0" dy="30">',
                _title,
                "</tspan></text>"
            );
    }

    function _quote(string memory str) internal pure returns (string memory) {
        return string.concat('"', str, '"');
    }
}
