pragma solidity ^0.8.23;

import "@openzeppelin/contracts/utils/Base64.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

import {Colors} from "../../libraries/svg/Colors.sol";
import {SVG} from "../../libraries/svg/SVG.sol";
import {JSON} from "../../libraries/svg/JSON.sol";
import "../../libraries/svg/HexStrings.sol";

contract Descriptor {
    using Strings for uint256;

    // -----------------------------------------------------------------
    // Internal
    // -----------------------------------------------------------------

    function _encode(bytes memory _svg) internal pure returns (string memory) {
        return _base64(_svg);
    }

    function _buildSVG(
        uint256 _tokenId,
        address _ownerAddress,
        string memory _symbol,
        uint256 _amount,
        uint256 _decimals,
        string storage _name
    ) internal pure returns (bytes memory) {
        string[] memory colors = Colors.toHEXColors(_ownerAddress);

        string memory supportAmount = SVG.formatted(_amount, _decimals, 5);

        bytes memory dynamicLayer = abi.encodePacked(
            SVG.sideText(
                _tokenId.toString(),
                "rotate(90 132.5 142.5)",
                "start"
            ),
            SVG.sideText(
                Strings.toHexString(_ownerAddress),
                "rotate(90 -107.5 382.5)",
                "end"
            ),
            SVG.titleStack(30, 110, "Pool", abi.encodePacked(_name)),
            SVG.titleStack(
                30,
                200,
                "Donation",
                abi.encodePacked(supportAmount, " ", _symbol)
            )
        );

        string memory gradient = SVG.gradient(colors);

        return
            abi.encodePacked(
                '<svg width="290" height="500" viewBox="0 0 290 500" xmlns="http://www.w3.org/2000/svg">',
                style,
                background,
                sideBox,
                logo,
                dynamicLayer,
                gradient,
                "</svg>"
            );
    }

    function _toDataURI(
        string memory image
    ) internal pure returns (string memory) {
        string[3] memory keys = ["name", "description", "image"];

        string[3] memory values = [
            "Zakat3",
            "Zakat3 Donation NFT",
            string.concat("data:image/svg+xml;base64,", image)
        ];

        return JSON.toJSON(keys, values);
    }

    function _base64(bytes memory data) internal pure returns (string memory) {
        return Base64.encode(data);
    }

    // -----------------------------------------------------------------
    // Constants
    // -----------------------------------------------------------------

    bytes constant style =
        // solhint-disable-next-line max-line-length
        "<style><![CDATA[text{font-family:Helvetica;font-weight:100}.alpha{opacity:0.5}.small{font-size:.8rem}.large{font-size:1.4rem}.huge{font-size:2rem}.title{fill:#fff}.bold{font-weight:bold}]]></style>";

    bytes constant logo =
        // solhint-disable-next-line max-line-length
        '<text class="title huge" fill="#FFF" transform="translate(30,60)"> <tspan class="bold">Zakat</tspan><tspan class="alpha">3</tspan></text>';

    bytes constant background =
        // solhint-disable-next-line max-line-length
