pragma solidity ^0.8.23;

import "@openzeppelin/contracts/access/manager/AccessManaged.sol";
import "@openzeppelin/contracts/utils/Base64.sol";
import "@openzeppelin/contracts/token/ERC721/ERC721.sol";

import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";

import {IZakat} from "../../interfaces/IZakat.sol";

import {Data} from "../../libraries/Data.sol";
import {Descriptor} from "./Descriptor.sol";
import {Registered} from "../registry/Registered.sol";

contract Zakat is IZakat, AccessManaged, ERC721, Descriptor, Registered {
    uint256 internal tokenId;

    string internal nativeAssetSymbol;

    mapping(uint256 => Data.Donation) internal donations;

    constructor(
        address _authority,
        address _registry,
        string memory _nativeAssetSymbol
    ) AccessManaged(_authority) ERC721("Zakat3", "ZKT") Registered(_registry) {
        nativeAssetSymbol = _nativeAssetSymbol;
    }

    // -----------------------------------------------------------------
    // External
    // -----------------------------------------------------------------

    function SVG(uint256 _tokenId) external view returns (string memory) {
        Data.Donation storage donation = donations[_tokenId];

        address owner = ownerOf(_tokenId);

        bytes memory svg = _buildSVG(
            _tokenId,
            owner,
            _getAssetSymbol(donation.asset),
            donation.amount,
            _getAssetDecimals(donation.asset),
            donation.name
        );

        return string(svg);
    }

    // -----------------------------------------------------------------
    // Public
    // -----------------------------------------------------------------

    function tokenURI(
        uint256 _tokenId
    ) public view override(ERC721, IZakat) returns (string memory) {
        Data.Donation storage donation = donations[_tokenId];

        address owner = ownerOf(_tokenId);

        bytes memory svg = _buildSVG(
            _tokenId,
            owner,
            _getAssetSymbol(donation.asset),
            donation.amount,
            _getAssetDecimals(donation.asset),
            donation.name
        );

        string memory image = _encode(svg);

        return _toDataURI(image);
    }

    // -----------------------------------------------------------------
    // Public (Access Managed)
    // -----------------------------------------------------------------

    function mint(
        address _recipient,
        address _asset,
        uint256 _amount,
        uint256 _pool,
        string memory _name
    ) public restricted returns (uint256) {
        _mint(_recipient, ++tokenId);

        donations[tokenId] = Data.Donation({
            donor: _recipient,
            amount: _amount,
            asset: _asset,
            pool: _pool,
            name: _name
        });

        emit Donated(_pool, _recipient, _asset, _amount);

        return tokenId;
    }

    // -----------------------------------------------------------------
    // Internal
    // -----------------------------------------------------------------

    function _getAssetSymbol(
        address _asset
    ) internal view returns (string memory) {
        if (_asset == address(0)) return nativeAssetSymbol;
        return IERC20Metadata(_asset).symbol();
    }

    function _getAssetDecimals(address _asset) internal view returns (uint256) {
        if (_asset == address(0)) return 18;
        return IERC20Metadata(_asset).decimals();
    }

    // -----------------------------------------------------------------
    // Events
    // -----------------------------------------------------------------

    event Donated(
        uint256 indexed pool,
        address indexed donator,
        address indexed asset,
        uint256 amount
    );
}
