pragma solidity ^0.8.23;

import "@openzeppelin/contracts/access/manager/AccessManaged.sol";

import {Errors} from "../../libraries/Errors.sol";

/**
 * @title A contract to act as a registry for other platform contracts to register themselves
 *        and to query for the current implementation address of other platform contracts.
 * @dev Inherits from OpenZeppelin's Ownable for ownership-based access control.
 */
contract Registry is AccessManaged {
    // Array to store registered contract names.
    bytes32[] private contracts;

    // Mapping from names (as bytes32) to addresses.
    mapping(bytes32 => address) private registry;

    constructor(address _authority) AccessManaged(_authority) {}

    /**
     * @dev Retrieves a list of all registered contract names.
     * @return bytes32[] A memory array of registered contract names.
     */
    function registered() public view returns (bytes32[] memory) {
        return contracts;
    }

    /**
     * @dev Retrieves the address associated with a given contract name.
     * @param _name The name of the contract to query.
     * @return address The contract address associated with the given name.
     * @notice If the name is not registered, the function reverts with the NotFound error.
     */
    function get(
        bytes32 _name
    ) public view whenRegistered(_name) returns (address) {
        return registry[_name];
    }

    /**
     * @dev Retrieves the addresses for a batch of contract names.
     * @param _names An array of contract names to query.
     * @return address[] An array of addresses associated with the given names.
     */
    function batchGet(
        bytes32[] memory _names
    ) public view returns (address[] memory) {
        uint256 length = _names.length;
        address[] memory addresses = new address[](length);

        for (uint256 i = 0; i < length; i++) {
            addresses[i] = get(_names[i]);
        }

        return addresses;
    }

    /**
     * @dev Registers a new contract name and address.
     * @param _name The name of the contract to register.
     * @param _address The Ethereum address of the contract.
     * @notice If the name is already registered, it returns true without modification.
     */
    function register(
        bytes32 _name,
        address _address
    ) public restricted whenNotRegistered(_name) {
        registry[_name] = _address;
        contracts.push(_name);
    }

    /**
     * @dev Registers multiple contract names and addresses in one transaction.
     * @param _name An array of contract names to register.
     * @param _address An array of Ethereum addresses of the contracts.
     * @notice Skips any name that is already registered.
     */
    function batchRegister(
        bytes32[] memory _name,
        address[] memory _address
    ) public restricted {
        uint256 length = _name.length;

        for (uint256 i = 0; i < length; i++) {
            if (registry[_name[i]] != address(0)) continue;
            registry[_name[i]] = _address[i];
            contracts.push(_name[i]);
        }
    }

    /**
     * @dev Updates the address for an existing contract name.
     * @param _name The name of the contract to update.
     * @param _address The new Ethereum address of the contract.
     * @notice If the name is not registered, it reverts with the NotFound error.
     */
    function update(
        bytes32 _name,
        address _address
    ) public restricted whenRegistered(_name) {
        registry[_name] = _address;
    }

    /**
     * @dev Updates the addresses for multiple contract names in one transaction.
     * @param _name An array of contract names to update.
     * @param _address An array of new Ethereum addresses for the contracts.
     */
    function batchUpdate(
        bytes32[] memory _name,
        address[] memory _address
    ) public restricted {
        uint256 length = _name.length;

        for (uint256 i = 0; i < length; i++) {
            if (registry[_name[i]] == address(0)) continue;
            registry[_name[i]] = _address[i];
        }
    }

    modifier whenRegistered(bytes32 _name) {
        if (registry[_name] == address(0)) revert Errors.NotFound();
        _;
    }

    modifier whenNotRegistered(bytes32 _name) {
        if (registry[_name] != address(0)) revert Errors.Registered();
        _;
    }
}
